def do_main():
    from xpra.os_util import SIGNAMES
    from xpra.scripts.main import InitExit, InitInfo
    from xpra.gtk_common.quit import gtk_main_quit_on_fatal_exceptions_enable
    gtk_main_quit_on_fatal_exceptions_enable()
    from xpra.platform.gui import ready as gui_ready
    gui_init()
    try:
        from xpra.scripts.parsing import parse_cmdline, fixup_debug_option
        (options, args) = parse_cmdline(sys.argv)
        debug = fixup_debug_option(options.debug)
        if debug:
            for x in debug.split(','):
                enable_debug_for(x)
    except InitInfo as e:
        print(str(e))
        return 0
    except InitExit as e:
        return e.status
    except Exception:
        exception_dialog('Error parsing command line')
        return 1
    from xpra.scripts import config
    config.debug = log.debug
    try:
        app = ApplicationWindow()

        def app_signal(signum, _frame):
            print('')
            log('got signal %s' % SIGNAMES.get(signum, signum))

            def show_signal():
                app.show()
                app.client.cleanup()
                glib.timeout_add(1000, app.set_info_text, 'got signal %s' % SIGNAMES.get(signum, signum))
                glib.timeout_add(1000, app.set_info_color, True)
            glib.idle_add(show_signal)
        if sys.version_info[0] < 3:
            signal.signal(signal.SIGINT, app_signal)
        signal.signal(signal.SIGTERM, app_signal)
        has_file = len(args) == 1
        if has_file:
            app.update_options_from_file(args[0])
            configure_network(app.config)
        debug = fixup_debug_option(app.config.debug)
        if debug:
            for x in debug.split(','):
                enable_debug_for(x)
        app.create_window_with_config()
    except Exception:
        exception_dialog('Error creating launcher form')
        return 1
    try:
        if app.config.autoconnect:
            glib.idle_add(app.do_connect)
        if not has_file:
            app.reset_errors()
        gui_ready()
        if not app.config.autoconnect or app.config.debug:
            if OSX:

                def force_show():
                    from xpra.platform.darwin.gui import enable_focus_workaround, disable_focus_workaround
                    enable_focus_workaround()
                    app.show()
                    glib.timeout_add(500, disable_focus_workaround)
                app.__osx_open_signal = False

                def do_open_file(filename):
                    log.info('do_open_file(%s)', filename)
                    app.update_options_from_file(filename)
                    configure_network(app.config)
                    app.update_gui_from_config()
                    if app.config.autoconnect:
                        app.__osx_open_signal = True
                        glib.idle_add(app.do_connect)
                    else:
                        force_show()

                def open_file(_, filename):
                    log.info('open_file(%s)', filename)
                    glib.idle_add(do_open_file, filename)

                def do_open_URL(url):
                    log.info('do_open_URL(%s)', url)
                    app.__osx_open_signal = True
                    app.update_options_from_URL(url)
                    configure_network(app.config)
                    app.update_gui_from_config()
                    glib.idle_add(app.do_connect)

                def open_URL(url):
                    log.info('open_URL(%s)', url)
                    glib.idle_add(do_open_URL, url)
                from xpra.platform.darwin.gui import get_OSXApplication, register_URL_handler
                register_URL_handler(open_URL)
                try:
                    get_OSXApplication().connect('NSApplicationOpenFile', open_file)
                except Exception as e:
                    log.error('Error: cannot handle file associations:')
                    log.error(' %s', e)

                def may_show():
                    log('may_show() osx open signal=%s', app.__osx_open_signal)
                    if not app.__osx_open_signal:
                        force_show()
                glib.timeout_add(500, may_show)
            else:
                app.show()
        app.run()
    except KeyboardInterrupt:
        pass
    return 0

def _retrieve(self, url):
    encode = 'latin1'
    try:
        uopener = self.urlOpener.open(url)
        content = uopener.read()
        info_dict = uopener.info()
        if info_dict.has_key('Content-Type'):
            ct_line = info_dict['Content-Type'].lower()
            csi = ct_line.find('charset=')
            if csi != -1:
                encode_candidate = ct_line[csi+9:]
                try:
                    lookup(encode_candidate)
                    encode = encode_candidate
                except (LookupError, ValueError, TypeError):
                    encode = 'latin1'
        uopener.close()
        self.urlOpener.close()
    except IOError, e:
        raise IMDbDataAccessError, {'errcode': e.errno,
                                    'errmsg': str(e.strerror),
                                    'url': url,
                                    'proxy': self.get_proxy()}
    return unicode(content, encode, 'replace')

def config_init(prompt=True):
    config_path = os.getcwd() + '/.wandb'
    config = Config()
    if os.path.isdir(config_path):
        if prompt:
            click.confirm(click.style('This directory is already initialized, should we overwrite it?', fg='red'), abort=True)
    else:
        tmp_path = config_path.replace('.wandb', '.wandb.tmp')
        if os.path.isfile(config_path):
            os.rename(config_path, tmp_path)
        os.mkdir(config_path)
        if os.path.isfile(tmp_path):
            os.rename(tmp_path, tmp_path.replace('.wandb.tmp', '.wandb/config'))
    config.batch_size_desc = 'Number of training examples in a mini-batch'
    config.batch_size = 32
    config.persist()
    if prompt:
        click.echo('Configuration initialized, use `wandb config set` to set parameters.  Then in your training script:\n\nimport wandb\nconf = wandb.Config()\nconf.batch_size\n')

def collect_from_file(urls_file, archive_dir=CONFIG.mail_path, notes=None):
    for url in open(urls_file):
        url = url.strip()
        if not url:
            continue
        collect_from_url(url, archive_dir=archive_dir, notes=notes)

def chunk_date_range(self, start_date: Union[int, str, datetime], end_date: Union[int, str, datetime], chunk_size: int, chunk_unit: Optional[str]='months', date_format: Optional[str]=None) -> Tuple[Union[datetime, str], Union[datetime, str]]:
    relative_delta_settings = {chunk_unit: +chunk_size}
    if isinstance(start_date, (int, str)):
        start_date = self.any_to_datetime(start_date)
    if isinstance(end_date, (int, str)):
        end_date = self.any_to_datetime(end_date)
    sd = start_date
    ed = min(end_date, start_date + relativedelta(**relative_delta_settings))
    while 1:
        sdf = sd
        edf = ed
        if date_format is not None:
            sdf = sd.format(date_format)
            edf = ed.format(date_format)
        yield (sdf, edf)
        if ed >= end_date:
            break
        sd = ed
        ed = min(end_date, sd + relativedelta(**relative_delta_settings))

def extend_substation_overloading(network, critical_stations):
    try:
        standard_transformer = network.equipment_data['mv_trafos'].loc[network.config['grid_expansion_standard_equipment']['hv_mv_transformer']]
    except KeyError:
        print('Standard HV/MV transformer is not in equipment list.')
    load_factor = network.config['grid_expansion_load_factors']['mv_feedin_case_transformer']
    transformers_changes = {'added': {}, 'removed': {}}
    for station in critical_stations:
        s_max_per_trafo = [_.type.S_nom for _ in station.transformers]
        s_station_pfa = critical_stations[station]
        s_trafo_missing = s_station_pfa - sum(s_max_per_trafo) * load_factor
        if max(s_max_per_trafo) >= s_trafo_missing:
            duplicated_transformer = min([_ for _ in station.transformers if _.type.S_nom > s_trafo_missing], key=lambda j: j.type.S_nom - s_trafo_missing)
            new_transformer = Transformer(id='MVStation_{}_transformer_{}'.format(str(station.id), str(len(station.transformers) + 1)), geom=duplicated_transformer.geom, grid=duplicated_transformer.grid, voltage_op=duplicated_transformer.voltage_op, type=copy.deepcopy(duplicated_transformer.type))
            station.add_transformer(new_transformer)
            transformers_changes['added'][station] = [new_transformer]
        else:
            station_transformer = station.transformers[0]
            number_transformers = math.ceil(s_station_pfa / standard_transformer.S_nom)
            new_transformers = []
            for i in range(number_transformers):
                new_transformer = Transformer(id='MVStation_{}_transformer_{}'.format(str(station.id), str(i + 1)), geom=station_transformer.geom, grid=station_transformer.grid, voltage_op=station_transformer.voltage_op, type=copy.deepcopy(standard_transformer))
                new_transformers.append(new_transformer)
            transformers_changes['added'][station] = new_transformers
            transformers_changes['removed'][station] = station.transformers
            station.transformers = new_transformers
    if transformers_changes['added']:
        logger.debug('==> MV station has been reinforced due to overloading issues.')
    return transformers_changes

