def level_check(self):
    if self.happiness > SETTLER.HAPPINESS_LEVEL_UP_REQUIREMENT:
        self.level_up()
        self.get_component(StorageComponent).inventory.alter(RES.CONSTRUCTION_MATERIAL, -1)
        self._changed()
    elif self.happiness < SETTLER.HAPPINESS_LEVEL_DOWN_LIMIT:
        self.level_down()
        self._changed()

