def maybe_adjust_fees(plugin: Plugin, scids: list):
    channels_adjusted = 0
    for scid in scids:
        if scid in plugin.exclude_list or get_peer_id_for_scid(plugin, scid) in plugin.exclude_list:
            continue
        our = plugin.adj_balances[scid]['our']
        total = plugin.adj_balances[scid]['total']
        percentage = our / total
        base = int(plugin.adj_basefee)
        ppm = int(plugin.adj_ppmfee)
        fees = plugin.fee_strategy(plugin, scid)
        if fees is not None:
            ppm = int(fees['ppm'])
            if plugin.basefee:
                base = int(fees['base'])
        if percentage > plugin.imbalance and percentage < 1 - plugin.imbalance:
            if setchannelfee(plugin, scid, base, ppm):
                plugin.log(f'Set default fees as imbalance is too low for {scid}:   ppm {ppm}   base {base}msat')
                plugin.adj_balances[scid]['last_liquidity'] = our
                channels_adjusted += 1
            continue
        if not significant_update(plugin, scid):
            continue
        percentage = get_adjusted_percentage(plugin, scid)
        assert 0 <= percentage and percentage <= 1, f'percentage is out of bounds: balances: {plugin.adj_balances[scid]} big_enough_liquidity: {int(plugin.big_enough_liquidity)}'
        ratio = plugin.get_ratio(percentage)
        if plugin.max_htlc_steps >= 1:
            max_htlc = int(total * math.ceil(plugin.max_htlc_steps * percentage) / plugin.max_htlc_steps)
        else:
            max_htlc = None
        if setchannelfee(plugin, scid, base, int(ppm * ratio), None, max_htlc):
            plugin.log(f'Adjusted fees of {scid} with a ratio of {ratio}:   ppm {int(ppm * ratio)}   base {base}msat   max_htlc {max_htlc}')
            plugin.adj_balances[scid]['last_liquidity'] = our
            channels_adjusted += 1
    plugin.log('maybe_adjust_fees done', 'debug')
    return channels_adjusted

def setChild(self, name, value):
    assert name == self.named_child, name
    if type(value) is list:
        value = tuple(value)
    if self.checker is not None:
        value = self.checker(value)
    if type(value) is tuple:
        for val in value:
            val.parent = self
    elif value is not None:
        value.parent = self
    attr_name = 'subnode_' + name
    if __debug__:
        old_value = getattr(self, attr_name)
        assert old_value is not value, value
    setattr(self, attr_name, value)

def POST(self, req):

    def object_key_iter(elem):
        for obj in elem.iterchildren('Object'):
            key = obj.find('./Key').text
            if not key:
                raise UserKeyMustBeSpecified()
            version = obj.find('./VersionId')
            if version is not None:
                version = version.text
            yield (key, version)
    max_body_size = min(2 * self.conf.max_multi_delete_objects * MAX_OBJECT_NAME_LENGTH, 10 * 1024 * 1024)
    try:
        xml = req.xml(max_body_size)
        if not xml:
            raise MissingRequestBodyError()
        req.check_md5(xml)
        elem = fromstring(xml, 'Delete', self.logger)
        quiet = elem.find('./Quiet')
        if quiet is not None and quiet.text.lower() == 'true':
            self.quiet = True
        else:
            self.quiet = False
        delete_list = list(object_key_iter(elem))
        if len(delete_list) > self.conf.max_multi_delete_objects:
            raise MalformedXML()
    except (XMLSyntaxError, DocumentInvalid):
        raise MalformedXML()
    except ErrorResponse:
        raise
    except Exception as e:
        self.logger.error(e)
        raise
    elem = Element('DeleteResult')
    try:
        req.get_response(self.app, 'HEAD')
    except AccessDenied as error:
        body = self._gen_error_body(error, elem, delete_list)
        return HTTPOk(body=body)
    if any((version is not None for (_key, version) in delete_list)):
        raise S3NotImplemented()

    def do_delete(base_req, key, version):
        req = copy.copy(base_req)
        req.environ = copy.copy(base_req.environ)
        req.object_name = key
        try:
            query = req.gen_multipart_manifest_delete_query(self.app)
            resp = req.get_response(self.app, method='DELETE', query=query, headers={'Accept': 'application/json'})
            if query:
                try:
                    delete_result = json.loads(resp.body)
                    if delete_result['Errors']:
                        msg_parts = [delete_result['Response Status']]
                        msg_parts.extend(('%s: %s' % (obj, status) for (obj, status) in delete_result['Errors']))
                        return (key, {'code': 'SLODeleteError', 'message': '\n'.join(msg_parts)})
                except (ValueError, TypeError, KeyError):
                    self.logger.exception('Could not parse SLO delete response: %r', resp.body)
                    return (key, {'code': 'SLODeleteError', 'message': 'Unexpected swift response'})
        except NoSuchKey:
            pass
        except ErrorResponse as e:
            return (key, {'code': e.__class__.__name__, 'message': e._msg})
        return (key, None)
    with StreamingPile(self.conf.multi_delete_concurrency) as pile:
        for (key, err) in pile.asyncstarmap(do_delete, ((req, key, version) for (key, version) in delete_list)):
            if err:
                error = SubElement(elem, 'Error')
                SubElement(error, 'Key').text = key
                SubElement(error, 'Code').text = err['code']
                SubElement(error, 'Message').text = err['message']
            elif not self.quiet:
                deleted = SubElement(elem, 'Deleted')
                SubElement(deleted, 'Key').text = key
    body = tostring(elem)
    return HTTPOk(body=body)

