def setkey(self, propname):
    if self.key:
        if propname == self.key:
            return
        iv_old = self.db._db.getas('_%s[k:S,i:I]' % self.classname)
        iv_old.clear()
        self.key = None
    prop = self.properties.get(propname, None)
    if prop is None:
        prop = self.privateprops.get(propname, None)
    if prop is None:
        raise KeyError, "no property %s" % propname
    if not isinstance(prop, hyperdb.String):
        raise TypeError, "%s is not a String" % propname
    self.key = propname
    iv = self.db._db.view('_%s' % self.classname)
    if self.db.fastopen and iv.structure():
        return
    self.db.dirty = 1
    iv = self.db._db.getas('_%s[k:S,i:I]' % self.classname)
    iv = iv.ordered(1)
    for row in self.getview():
        iv.append(k=getattr(row, propname), i=row.id)
    self.db.commit()

def create(entity_type=None, entity_id=None):
    if not (entity_id or entity_type):
        for allowed_type in ENTITY_TYPES:
            if (mbid := request.args.get(allowed_type)):
                entity_type = allowed_type
                entity_id = mbid
                break
        if entity_type:
            return redirect(url_for('.create', entity_type=entity_type, entity_id=entity_id))
        flash.info(gettext('Please choose an entity to review.'))
        return redirect(url_for('search.selector', next=url_for('.create')))
    if entity_type not in ENTITY_TYPES:
        raise BadRequest("You can't write reviews about this type of entity.")
    if current_user.is_blocked:
        flash.error(gettext('You are not allowed to write new reviews because your account has been blocked by a moderator.'))
        return redirect(url_for('user.reviews', user_id=current_user.id))
    (reviews, count) = db_review.list_reviews(user_id=current_user.id, entity_id=entity_id, inc_drafts=True, inc_hidden=True)
    review = reviews[0] if count != 0 else None
    if review:
        if review['is_draft']:
            return redirect(url_for('review.edit', id=review['id']))
        elif review['is_hidden']:
            return redirect(url_for('review.entity', id=review['id']))
        else:
            flash.error(gettext('You have already published a review for this entity'))
            return redirect(url_for('review.entity', id=review['id']))
    if current_user.is_review_limit_exceeded:
        flash.error(gettext('You have exceeded your limit of reviews per day.'))
        return redirect(url_for('user.reviews', user_id=current_user.id))
    form = ReviewCreateForm(default_license_id=current_user.license_choice, default_language=get_locale())
    if form.validate_on_submit():
        is_draft = form.state.data == 'draft'
        if form.text.data == '':
            form.text.data = None
        review = db_review.create(user_id=current_user.id, entity_id=entity_id, entity_type=entity_type, text=form.text.data, rating=form.rating.data, license_id=form.license_choice.data, language=form.language.data, is_draft=is_draft)
        if form.remember_license.data:
            db_users.update(current_user.id, user_new_info={'license_choice': form.license_choice.data})
        if is_draft:
            flash.success(gettext('Review has been saved!'))
        else:
            flash.success(gettext('Review has been published!'))
        return redirect(url_for('.entity', id=review['id']))
    try:
        _entity = get_entity_by_id(entity_id, entity_type)
        data = {'form': form, 'entity_type': entity_type, 'entity': _entity}
    except NoDataFoundException:
        raise NotFound(gettext("Sorry, we couldn't find a %s with that MusicBrainz ID." % entity_type))
    if not _entity:
        flash.error(gettext('You can only write a review for an entity that exists on MusicBrainz!'))
        return redirect(url_for('search.selector', next=url_for('.create')))
    data['entity_title'] = get_entity_title(_entity)
    if entity_type == 'release_group':
        data['spotify_mappings'] = mbspotify.mappings(entity_id)
        data['soundcloud_url'] = soundcloud.get_url(entity_id)
    if not form.errors:
        flash.info(gettext('Please provide some text or a rating for this review.'))
    return render_template('review/modify/write.html', **data)

def send_msg(msg, server='localhost', port='6667', channel=None, nick_to=None, key=None, topic=None, nick='ansible', color='none', passwd=False, timeout=30, use_ssl=False, part=True, style=None):
    nick_to = [] if nick_to is None else nick_to
    colornumbers = {'white': '00', 'black': '01', 'blue': '02', 'green': '03', 'red': '04', 'brown': '05', 'purple': '06', 'orange': '07', 'yellow': '08', 'light_green': '09', 'teal': '10', 'light_cyan': '11', 'light_blue': '12', 'pink': '13', 'gray': '14', 'light_gray': '15'}
    stylechoices = {'bold': '\x02', 'underline': '\x1f', 'reverse': '\x16', 'italic': '\x1d'}
    try:
        styletext = stylechoices[style]
    except Exception:
        styletext = ''
    try:
        colornumber = colornumbers[color]
        colortext = '\x03' + colornumber
    except Exception:
        colortext = ''
    message = styletext + colortext + msg
    irc = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    if use_ssl:
        if getattr(ssl, 'PROTOCOL_TLS', None) is not None:
            context = ssl.create_default_context()
        else:
            context = ssl.SSLContext()
        context.verify_mode = ssl.CERT_NONE
        irc = context.wrap_socket(irc)
    irc.connect((server, int(port)))
    if passwd:
        irc.send(to_bytes('PASS %s\r\n' % passwd))
    irc.send(to_bytes('NICK %s\r\n' % nick))
    irc.send(to_bytes('USER %s %s %s :ansible IRC\r\n' % (nick, nick, nick)))
    motd = ''
    start = time.time()
    while 1:
        motd += to_native(irc.recv(1024))
        match = re.search('^:\\S+ 00[1-4] (?P<nick>\\S+) :', motd, flags=re.M)
        if match:
            nick = match.group('nick')
            break
        elif time.time() - start > timeout:
            raise Exception('Timeout waiting for IRC server welcome response')
        time.sleep(0.5)
    if channel:
        if key:
            irc.send(to_bytes('JOIN %s %s\r\n' % (channel, key)))
        else:
            irc.send(to_bytes('JOIN %s\r\n' % channel))
        join = ''
        start = time.time()
        while 1:
            join += to_native(irc.recv(1024))
            if re.search('^:\\S+ 366 %s %s :' % (nick, channel), join, flags=re.M | re.I):
                break
            elif time.time() - start > timeout:
                raise Exception('Timeout waiting for IRC JOIN response')
            time.sleep(0.5)
        if topic is not None:
            irc.send(to_bytes('TOPIC %s :%s\r\n' % (channel, topic)))
            time.sleep(1)
    if nick_to:
        for nick in nick_to:
            irc.send(to_bytes('PRIVMSG %s :%s\r\n' % (nick, message)))
    if channel:
        irc.send(to_bytes('PRIVMSG %s :%s\r\n' % (channel, message)))
    time.sleep(1)
    if part:
        if channel:
            irc.send(to_bytes('PART %s\r\n' % channel))
        irc.send(to_bytes('QUIT\r\n'))
        time.sleep(1)
    irc.close()

def excerpt(self, source_paths, workdir, conform):
    encoding = conform.get('encoding')
    csvsplit = conform.get('csvsplit', ',')
    known_paths = ExcerptDataTask._get_known_paths(source_paths, workdir, conform, self.known_types)
    if not known_paths:
        return (None, None)
    data_path = known_paths[0]
    (_, data_ext) = os.path.splitext(data_path.lower())
    if data_ext in ('.geojson', '.json'):
        data_path = ExcerptDataTask._sample_geojson_file(data_path)
    format_string = conform.get('format')
    if format_string == 'csv':
        return ExcerptDataTask._excerpt_csv_file(data_path, encoding, csvsplit)
    ogr_data_path = normalize_ogr_filename_case(data_path)
    datasource = ogr.Open(ogr_data_path, 0)
    layer = datasource.GetLayer()
    if not encoding:
        encoding = guess_source_encoding(datasource, layer)
    if data_ext == '.csv' and encoding not in ('utf8', 'utf-8'):
        return ExcerptDataTask._excerpt_csv_file(data_path, encoding, csvsplit)
    layer_defn = layer.GetLayerDefn()
    fieldcount = layer_defn.GetFieldCount()
    fieldnames = [layer_defn.GetFieldDefn(i).GetName() for i in range(fieldcount)]
    fieldnames = [f.decode(encoding) if hasattr(f, 'decode') else f for f in fieldnames]
    data_sample = [fieldnames]
    for (feature, _) in zip(layer, range(5)):
        row = [feature.GetField(i) for i in range(fieldcount)]
        row = [v.decode(encoding) if hasattr(v, 'decode') else v for v in row]
        data_sample.append(row)
    if len(data_sample) < 2:
        raise ValueError('Not enough rows in data source')
    if layer_defn.GetGeomType() in geometry_types:
        geometry_type = geometry_types.get(layer_defn.GetGeomType(), None)
    elif fieldnames[-3:] == [X_FIELDNAME, Y_FIELDNAME, GEOM_FIELDNAME]:
        geometry = ogr.CreateGeometryFromWkt(data_sample[1][-1])
        geometry_type = geometry_types.get(geometry.GetGeometryType(), None)
    else:
        geometry_type = None
    return (data_sample, geometry_type)

def __init__(self, model: openvino.runtime.Model, parent_model: OVBaseModel, ov_config: Optional[Dict[str, str]]=None, model_name: str='encoder', model_dir: str=None):
    self.model = model
    self.parent_model = parent_model
    self.input_names = {key.get_any_name(): idx for (idx, key) in enumerate(self.model.inputs)}
    self.input_dtype = {inputs.get_any_name(): OV_TO_NP_TYPE[inputs.get_element_type().get_type_name()] for inputs in self.model.inputs}
    self.ov_config = ov_config or {**self.parent_model.ov_config}
    self.request = None
    self._model_name = model_name
    self._model_dir = Path(model_dir or parent_model._model_save_dir)
    config_path = self._model_dir / model_name / self.CONFIG_NAME
    self.config = self.parent_model._dict_from_json_file(config_path) if config_path.is_file() else {}
    if self._model_dir.is_dir() and self._model_dir.samefile(Path(gettempdir())):
        return
    if 'CACHE_DIR' not in self.ov_config:
        self.ov_config['CACHE_DIR'] = os.path.join(self._model_dir, self._model_name)

def validateTexturePath(path):
    path = expand_path(path)
    if not os.path.exists(path):
        raise ValidationException('%r does not exist.' % path)
    return path

def update(self, **kwargs):
    if self.can_update:
        project_update = self.project_updates.create(scm_url=self.scm_url, scm_branch=self.scm_branch, scm_type=self.scm_type, scm_refspec=self.scm_refspec, scm_clean=self.scm_clean, scm_delete_on_update=self.scm_delete_on_update, scm_track_submodules=self.scm_track_submodules, credential=self.credential, timeout=self.timeout)
        if hasattr(settings, 'CELERY_UNIT_TEST'):
            project_update.start(None, **kwargs)
        else:
            project_update.signal_start(**kwargs)
        return project_update

def update(self, **kwargs):
    if self.can_update:
        project_update = self.project_updates.create(scm_url=self.scm_url, scm_branch=self.scm_branch, scm_type=self.scm_type, scm_refspec=self.scm_refspec, scm_clean=self.scm_clean, scm_delete_on_update=self.scm_delete_on_update, scm_track_submodules=self.scm_track_submodules, credential=self.credential, timeout=self.timeout)
        if hasattr(settings, 'CELERY_UNIT_TEST'):
            project_update.start(None, **kwargs)
        else:
            project_update.signal_start(**kwargs)
        return project_update

def on_task_metainfo(self, task, config):
    for entry in task.entries:
        snapshot = entry.snapshots.get('after_input')
        if snapshot:
            continue
        entry.take_snapshot('after_input')

def on_task_metainfo(self, task, config):
    for entry in task.entries:
