        if snapshot:
            continue
        entry.take_snapshot('after_input')

def next(self):
    if self._stop_iteration:
        raise StopIteration
    elif self._has_saved:
        self._has_saved = False
        return self._saved
    else:
        return self._generator.next()

def next(self):
    if self._stop_iteration:
        raise StopIteration
    elif self._has_saved:
        self._has_saved = False
        return self._saved
    else:
        return self._generator.next()

def _reset(self):
    self.agentPos = self.startPos
    self.agentDir = 0
    self.stepCount = 0
    return np.array([])

def find_target_size(model_name):
    target_sizes = {'VGG-Face': (224, 224), 'Facenet': (160, 160), 'Facenet512': (160, 160), 'OpenFace': (96, 96), 'DeepFace': (55, 47), 'DeepID': (152, 152), 'Dlib': (150, 150), 'ArcFace': (112, 112), 'SFace': (112, 112)}
    if model_name not in target_sizes.keys():
        raise ValueError(f'unimplemented model name - {model_name}')
    return target_sizes[model_name]

def copy(self):
    self.temp_dir = tempfile.mkdtemp(suffix='', prefix='barman-')
    try:
        self._progress_init()
        _logger.info('Copy started (safe before %r)', self.safe_horizon)
        for item in self.item_list:
            if not item.is_directory:
                continue
            _logger.info(self._progress_message('analyze %s' % item))
            self._analyze_directory(item)
            _logger.info(self._progress_message('create destination directories and delete unknown files for %s' % item))
            self._create_dir_and_purge(item)
        pool = Pool(processes=self.workers, initializer=_init_worker, initargs=(self._execute_job,))
        for _ in pool.imap_unordered(_run_worker, self._job_generator()):
            pass
        for item in self.item_list:
            if item.item_class == self.PGCONTROL_CLASS:
                _logger.info(self._progress_message('executing final step for %s' % item))
                self._execute_job(item)
    except:
        _logger.info('Copy failed (safe before %s)', self.safe_horizon)
        raise
    else:
        _logger.info('Copy finished (safe before %s)', self.safe_horizon)
    finally:
        shutil.rmtree(self.temp_dir)
        self.temp_dir = None

def subset_for(self, selected_asset_keys: AbstractSet[AssetKey]) -> 'AssetsDefinition':
    check.invariant(self.can_subset, f'Attempted to subset AssetsDefinition for {self.node_def.name}, but can_subset=False.')
    return AssetsDefinition(keys_by_input_name=self._keys_by_input_name, keys_by_output_name=self._keys_by_output_name, node_def=self.node_def, partitions_def=self.partitions_def, partition_mappings=self._partition_mappings, asset_deps=self._asset_deps, can_subset=self.can_subset, selected_asset_keys=selected_asset_keys & self.keys, resource_defs=self.resource_defs, group_names_by_key=self.group_names_by_key)

def _update_job(self, job_id, state=None, **kwargs):
    with self.session_scope() as session:
        try:
            (job, orm_job) = self._get_job_and_orm_job(job_id, session)
            if state is not None:
                orm_job.state = state
            for kwarg in kwargs:
                setattr(job, kwarg, kwargs[kwarg])
            orm_job.obj = job
            session.add(orm_job)
            return (job, orm_job)
        except JobNotFound:
            if state:
                logger.error('Tried to update job with id {} with state {} but it was not found'.format(job_id, state))
            else:
                logger.error('Tried to update job with id {} but it was not found'.format(job_id))

def _generateColumnHeader(self, obj, **args):
    result = []
    try:
        role = args.get('role', obj.getRole())
    except:
        role = None
    if role in [pyatspi.ROLE_COLUMN_HEADER, pyatspi.ROLE_TABLE_COLUMN_HEADER]:
        return result
    try:
        table = obj.parent.queryTable()
    except:
        pass
    else:
        index = self._script.utilities.cellIndex(obj)
        columnIndex = table.getColumnAtIndex(index)
        if columnIndex >= 0:
            header = table.getColumnHeader(columnIndex)
            desc = None
            if header:
                desc = self._script.utilities.displayedText(header)
            if not desc:
                desc = table.getColumnDescription(columnIndex)
            if desc and len(desc):
                text = desc
                if args['mode'] == 'speech':
                    if settings.speechVerbosityLevel == settings.VERBOSITY_LEVEL_VERBOSE and (not args.get('formatType', None) in ['basicWhereAmI', 'detailedWhereAmI']):
                        text = desc + ' ' + self.getLocalizedRoleName(obj, pyatspi.ROLE_COLUMN_HEADER)
                elif args['mode'] == 'braille':
                    text = desc + ' ' + self.getLocalizedRoleName(obj, pyatspi.ROLE_COLUMN_HEADER)
                result.append(text)
    return result

def get_sequence(self, name):
    if name in self.saved_sequences:
        with open(self.sequence_dir + name + '.seq', 'rb') as infile:
            sequence = pickle.load(infile)
    else:
        sequence = None
        self.log.warning('Error: No sequence with name "{}" in saved sequences.'.format(name))
    return sequence

def _check_chunk_length(self, cursor, value):
    if self.cluster.version() >= '3.0':
        table_metadata = cursor.metadata.keyspaces['ks'].tables['test_table']
    else:
        table_metadata = cursor.metadata.keyspaces['ks'].tables['test_table']
    params = table_metadata.options
    assert 'sstable_compression' in params, "Looking for a row with the string 'sstable_compression', but could not find it."
    chunk_length = int(params['chunk_length_kb'])
    assert chunk_length == value, 'Expected chunk_length: %s.  We got: %s' % (value, chunk_length)

def _check_chunk_length(self, cursor, value):
    if self.cluster.version() >= '3.0':
        table_metadata = cursor.metadata.keyspaces['ks'].tables['test_table']
    else:
        table_metadata = cursor.metadata.keyspaces['ks'].tables['test_table']
    params = table_metadata.options['sstable_compression']
    assert params is not '', "Looking for a row with the string 'sstable_compression', but could not find it."
    chunk_length = int(params['chunk_length_kb'])
    assert chunk_length == value, 'Expected chunk_length: %s.  We got: %s' % (value, chunk_length)

def __str__(self):
    modifiers = ' '.join(self.type_modifiers)
    syntax = ''
    if self.reference:
        syntax += '&'
    if self.pointer:
        syntax += '*'
    suffix = '%s %s%s %s' % (modifiers, self.type_name, syntax, self.name)
    if self.default:
        suffix += ' = ' + self.default
    return self._StringHelper(self.__class__.__name__, suffix)

def decrypt(self):
    value = self.parameters.get('CiphertextBlob')
    encryption_context = self.parameters.get('EncryptionContext', {})
    if encryption_context != self.kms_backend.get_encryption_context(value):
        raise ValueError('EncryptionContext does not match.')
    try:
        return json.dumps({'Plaintext': base64.b64decode(value).decode('utf-8'), 'KeyId': 'key_id'})
    except UnicodeDecodeError:
        return json.dumps({'Plaintext': value})

def genome_map(_input, max_wraps=0):
    from utilities.helper_methods import python_filter
    (used_input, current_depth, current_max_depth, nodes) = (0, 0, 0, 1)
    (wraps, output, production_choices) = (-1, [], [])
    unexpanded_symbols = [(params['BNF_GRAMMAR'].start_rule, 0)]
    while wraps < max_wraps and len(unexpanded_symbols) > 0 and (current_max_depth <= params['MAX_TREE_DEPTH']):
        if used_input % len(_input) == 0 and used_input > 0 and any([i[0][1] == 'NT' for i in unexpanded_symbols]):
            wraps += 1
        current_item = unexpanded_symbols.pop(0)
        (current_symbol, current_depth) = (current_item[0], current_item[1])
        if current_max_depth < current_depth:
            current_max_depth = current_depth
        if current_symbol[1] != params['BNF_GRAMMAR'].NT:
            output.append(current_symbol[0])
        else:
            production_choices = params['BNF_GRAMMAR'].rules[current_symbol[0]]
            current_production = _input[used_input % len(_input)] % len(production_choices)
            used_input += 1
            children = []
            for prod in production_choices[current_production]:
                children.append([prod, current_depth + 1])
            NT_kids = [child for child in children if child[0][1] == 'NT']
            if any(NT_kids):
                nodes += len(NT_kids)
            else:
                nodes += 1
            unexpanded_symbols = children + unexpanded_symbols
    if len(unexpanded_symbols) > 0:
        return (output, _input, None, nodes, True, current_max_depth + 1, used_input)
    output = ''.join(output)
    if params['BNF_GRAMMAR'].python_mode:
        output = python_filter(output)
    return (output, _input, None, nodes, False, current_max_depth + 1, used_input)

