def visit_Data_Implied_Do(self, o, **kwargs):
    loop_var = self.visit(o.children[0], **kwargs) if len(o.children) > 0 else None
    loop_bounds = self.visit(o.children[1], **kwargs) if len(o.children) > 1 else None
    data_values = self.visit(o.children[2], **kwargs) if len(o.children) > 2 else None
    return ir.DataImpliedDo(variable=loop_var, bounds=loop_bounds, values=data_values, label=kwargs.get('label'), source=kwargs.get('source'))

def test_run_qobj(self):
    try:
        simulator = qiskitsimulator.QISKitCppSimulator()
    except FileNotFoundError as fnferr:
        raise unittest.SkipTest('cannot find {} in path'.format(fnferr))
    result = simulator.run(self.q_job)
    expected2 = {'000 000': 18, '001 001': 15, '010 010': 13, '011 011': 11, '100 100': 10, '101 101': 10, '110 110': 12, '111 111': 11}
    self.assertEqual(result.get_counts('test_circuit2'), expected2)

