def save_run_results(cls, samples, key, run_results, overwrite=True, cache=True):
    if key is None:
        return
    dataset = samples._root_dataset
    run_docs = getattr(dataset._doc, cls._runs_field())
    run_doc = run_docs[key]
    if run_doc.results:
        if overwrite:
            run_doc.results.delete()
        else:
            raise ValueError("%s with key '%s' already has results" % (cls._run_str().capitalize(), key))
    if run_results is None:
        run_doc.results = None
    else:
        results_bytes = run_results.to_str().encode()
        run_doc.results.put(results_bytes, content_type='application/json')
    if cache:
        results_cache = getattr(dataset, cls._results_cache_field())
        results_cache[key] = run_results
    dataset._doc.save()

def save_run_results(cls, samples, key, run_results, overwrite=True, cache=True):
    if key is None:
        return
    dataset = samples._root_dataset
    run_doc = cls._get_run_doc(samples, key)
    if run_doc.results:
        if overwrite:
            run_doc.results.delete()
        else:
            raise ValueError("%s with key '%s' already has results" % (cls._run_str().capitalize(), key))
    if run_results is None:
        run_doc.results = None
    else:
        results_bytes = json_util.dumps(run_results.serialize()).encode()
        run_doc.results.put(results_bytes, content_type='application/json')
    if cache:
        results_cache = getattr(dataset, cls._results_cache_field())
        results_cache[key] = run_results
    run_doc.save()

def make_flask_test_suite(*test_cases):
    from operator import add
    db_settings = {'PostgreSQL': {'engine': 'postgresql'}, 'SQLite': {'engine': 'sqlite+pysqlite', 'username': None, 'password': None, 'host': None, 'database': None}}
    create_type = lambda c: [type(k + c.__name__, (c,), d) for (k, d) in db_settings.iteritems()]
    return unittest.TestSuite([unittest.makeSuite(case, 'test') for case in reduce(add, map(create_type, test_cases))])

