def __valueDoubleClick(self, widget, event):
    if event.button != event.Buttons.Left:
        return False
    if not self.__inspectorResults:
        return False
    if all((r.editable() for r in self.__inspectorResults)):
        self.__popup = GafferUI.PlugPopup(list({r.acquireEdit() for r in self.__inspectorResults}), warning=self.__formatWarnings([r.editWarning() for r in self.__inspectorResults]))
        if isinstance(self.__popup.plugValueWidget(), GafferUI.TweakPlugValueWidget):
            self.__popup.plugValueWidget().setNameVisible(False)
            self.__popup.popup()
    else:
        PopupWindow = GafferUI.PlugPopup.__bases__[0]
        with PopupWindow() as self.__popup:
            with GafferUI.ListContainer(GafferUI.ListContainer.Orientation.Horizontal, spacing=4):
                GafferUI.Image('warningSmall.png')
                GafferUI.Label('<h4>{}</h4>'.format(self.__formatWarnings([r.nonEditableReason() for r in self.__inspectorResults])))
        self.__popup.popup()
    return True

def __valueDoubleClick(self, widget, event):
    if event.button != event.Buttons.Left:
        return False
    if not self.__inspectorResults:
        return False
    if all((r.editable() for r in self.__inspectorResults)):
        self.__popup = GafferUI.PlugPopup(list({r.acquireEdit() for r in self.__inspectorResults}), warning=self.__formatWarnings([r.editWarning() for r in self.__inspectorResults]))
        if isinstance(self.__popup.plugValueWidget(), GafferUI.TweakPlugValueWidget):
            self.__popup.plugValueWidget().setNameVisible(False)
            self.__popup.popup()
    else:
        PopupWindow = GafferUI.PlugPopup.__bases__[0]
        with PopupWindow() as self.__popup:
            with GafferUI.ListContainer(GafferUI.ListContainer.Orientation.Horizontal, spacing=4):
                GafferUI.Image('warningSmall.png')
                GafferUI.Label('<h4>{}</h4>'.format(self.__formatWarnings([r.nonEditableReason() for r in self.__inspectorResults])))
        self.__popup.popup()
    return True

def visit_Module(self, node) -> str:
    docstring = getattr(node, 'docstring_comment', None)
    buf = [self.comment(docstring.value)] if docstring is not None else []
    filename = getattr(node, '__file__', None)
    self._imported_names = {}
    self._usings.clear()
    if filename is not None:
        self._module = Path(filename).stem
    body_dict: Dict[ast.AST, str] = OrderedDict()
    for b in node.body:
        if not isinstance(b, ast.FunctionDef):
            body_dict[b] = self.visit(b)
    for b in node.body:
        if isinstance(b, ast.FunctionDef):
            body_dict[b] = self.visit(b)
    buf += [body_dict[b] for b in node.body]
    return '\n'.join(buf)

def visit_Module(self, node) -> str:
    docstring = getattr(node, 'docstring_comment', None)
    buf = [self.comment(docstring.value)] if docstring is not None else []
    filename = getattr(node, '__file__', None)
    self._reset()
    if filename is not None:
        self._module = Path(filename).stem
    self._imported_names = {}
    self._usings.clear()
    body_dict: Dict[ast.AST, str] = OrderedDict()
    for b in node.body:
        if not isinstance(b, ast.FunctionDef):
            body_dict[b] = self.visit(b)
    for b in node.body:
        if isinstance(b, ast.FunctionDef):
            body_dict[b] = self.visit(b)
    buf += [body_dict[b] for b in node.body]
    return '\n'.join(buf)

def _check_error(self, value):
    if value != CKR_OK:
        if value in ERROR_CODES:
            raise P11CryptoPluginException(u._('HSM returned response code: {hex_value} {code}').format(hex_value=hex(value), code=ERROR_CODES[value]))
        else:
            raise P11CryptoPluginException(u._('HSM returned an unknown response code: {hex_value}').format(hex_value=hex(value)))

def setitem_from_path(self, path, value, trans=None):
    (path, item) = (path[:-1], path[-1])
    struct = self.struct
    for p in range(len(path)):
        part = path[p]
        if part.startswith('['):
            struct = struct[eval(part[1:-1])]
        else:
            struct = struct[part]
        if struct is None:
            return
    if isinstance(struct, (list, tuple)):
        pos = int(item)
        if pos < len(struct):
            struct[int(item)] = value
    elif isinstance(struct, dict):
        struct[item] = value
    elif hasattr(struct, item):
        setattr(struct, item, value)
    else:
        return
    self.update_db(trans)

def setitem_from_path(self, path, value, trans=None):
