        if part.startswith('['):
            struct = struct[eval(part[1:-1])]
        else:
            struct = struct[part]
        if struct is None:
            return
    if isinstance(struct, (list, tuple)):
        pos = int(item)
        if pos < len(struct):
            struct[int(item)] = value
    elif isinstance(struct, dict):
        if item in struct.keys():
            struct[item] = value
    elif hasattr(struct, item):
        setattr(struct, item, value)
    else:
        return
    self.update_db(trans)

