def __init__(self, task_list, filter_=None):
    self.filter = filter_
    self.targets = {}
    self.task_order = []
    self.tasks = {}
    for task in task_list:
        if not isinstance(task, BaseTask):
            msg = 'Task must an instance of BaseTask class. %s'
            raise InvalidTask(msg % task.__class__)
        if task.name in self.tasks:
            msg = 'Task names must be unique. %s'
            raise InvalidDodoFile(msg % task.name)
        self.tasks[task.name] = task
        self.task_order.append(task.name)
    for task in self.tasks.itervalues():
        for dep in task.task_dep:
            if dep not in self.tasks:
                msg = "%s. Task dependency '%s' does not exist."
                raise InvalidTask(msg % (task.name, dep))
    for task in self.tasks.itervalues():
        for target in task.targets:
            if target in self.targets:
                pass
            self.targets[target] = task
    for task in self.tasks.itervalues():
        for dep in task.file_dep:
            if dep in self.targets and self.targets[dep] not in task.task_dep:
                task.task_dep.append(self.targets[dep].name)

def get_site_coordination_environment(self, site, isite=None, dequivsite=None, dthissite=None, mysym=None, return_map=False):
    if isite is None:
        [isite, dequivsite, dthissite, mysym] = self.equivalent_site_index_and_transform(site)
    neighbors_normalized_distances = self.structure_environments.voronoi.neighbors_normalized_distances[isite]
    neighbors_normalized_angles = self.structure_environments.voronoi.neighbors_normalized_angles[isite]
    idist = None
    for (iwd, wd) in enumerate(neighbors_normalized_distances):
        if self.distance_cutoff >= wd['min']:
            idist = iwd
        else:
            break
    iang = None
    for (iwa, wa) in enumerate(neighbors_normalized_angles):
        if self.angle_cutoff <= wa['max']:
            iang = iwa
        else:
            break
    if idist is None or iang is None:
        raise ValueError('Distance or angle parameter not found ...')
    my_cn = None
    my_inb_set = None
    found = False
    for (cn, nb_sets) in self.structure_environments.neighbors_sets[isite].items():
        for (inb_set, nb_set) in enumerate(nb_sets):
            sources = [src for src in nb_set.sources if src['origin'] == 'dist_ang_ac_voronoi' and src['ac'] == self.additional_condition]
            for src in sources:
                if src['idp'] == idist and src['iap'] == iang:
                    my_cn = cn
                    my_inb_set = inb_set
                    found = True
                    break
            if found:
                break
        if found:
            break
    if not found:
        return None
    cn_map = (my_cn, my_inb_set)
    ce = self.structure_environments.ce_list[self.structure_environments.sites_map[isite]][cn_map[0]][cn_map[1]]
    if ce is None:
        return None
    coord_geoms = ce.coord_geoms
    if return_map:
        if coord_geoms is None:
            return (cn_map[0], cn_map)
        return (ce.minimum_geometry(symmetry_measure_type=self._symmetry_measure_type), cn_map)
    if coord_geoms is None:
        return cn_map[0]
    return ce.minimum_geometry(symmetry_measure_type=self._symmetry_measure_type)

def resample_and_save(predicted: Union[str, np.ndarray], target_shape: List[int], output_file: str, plans_dict_or_file: Union[dict, str], configuration_name: str, properties_dict: dict, dataset_json_dict_or_file: Union[dict, str], next_configuration: str) -> None:
    if isinstance(predicted, str):
        assert isfile(predicted), 'If isinstance(segmentation_softmax, str) then isfile(segmentation_softmax) must be True'
        del_file = deepcopy(predicted)
        predicted = np.load(predicted)
        os.remove(del_file)
    if isinstance(plans_dict_or_file, str):
        plans_dict_or_file = load_json(plans_dict_or_file)
    if isinstance(dataset_json_dict_or_file, str):
        dataset_json_dict_or_file = load_json(dataset_json_dict_or_file)
    resampling_fn = recursive_find_resampling_fn_by_name(plans_dict_or_file['configurations'][configuration_name]['resampling_fn_softmax'])
    current_spacing = plans_dict_or_file['configurations'][configuration_name]['spacing'] if len(plans_dict_or_file['configurations'][configuration_name]['spacing']) == len(properties_dict['shape_after_cropping_and_before_resampling']) else [properties_dict['spacing'][0], *plans_dict_or_file['configurations'][configuration_name]['spacing']]
    target_spacing = plans_dict_or_file['configurations'][next_configuration]['spacing'] if len(plans_dict_or_file['configurations'][next_configuration]['spacing']) == len(properties_dict['shape_after_cropping_and_before_resampling']) else [properties_dict['spacing'][0], *plans_dict_or_file['configurations'][next_configuration]['spacing']]
    predicted_array_or_file = resampling_fn(predicted, target_shape, current_spacing, target_spacing, **plans_dict_or_file['configurations'][configuration_name]['resampling_fn_softmax_kwargs'])
    use_regions = any([isinstance(i, tuple) and len(i) > 1 for i in dataset_json_dict_or_file['labels'].values()])
    if use_regions:
        regions_class_order = dataset_json_dict_or_file['regions_class_order']
        segmentation = np.zeros(predicted_array_or_file.shape[1:], dtype=np.uint8)
        for (i, c) in enumerate(regions_class_order):
            segmentation[predicted_array_or_file[i] > 0.5] = c
    else:
        segmentation = predicted_array_or_file.argmax(0)
    np.savez_compressed(output_file, seg=segmentation.astype(np.uint8))

