def aistudio_download(repo_id: str, filename: str, cache_dir: Optional[str]=None, revision: Optional[str]=None):
    res = download(repo_id=repo_id, filename=filename)
    if 'path' in res:
        return res['path']
    elif res['error_code'] == 10001:
        raise ValueError('Illegal argument error')
    elif res['error_code'] == 10002:
        raise UnauthorizedError('Unauthorized Access. Please ensure that you have provided the AIStudio Access Token and you have access to the requested asset')
    elif res['error_code'] == 12001:
        raise EntryNotFoundError(f"Cannot find the requested file '{filename}' in repo '{repo_id}'")
    else:
        raise Exception(f'Unknown error: {res}')

def copr_add_build(username, coprname):
    form = forms.BuildForm()
    copr = coprs_logic.CoprsLogic.get(flask.g.user, username, coprname).first()
    if not copr:
        return page_not_found('Copr with name {0} does not exist.'.format(coprname))
    if form.validate_on_submit() and flask.g.user.can_build_in(copr):
        build = models.Build(pkgs=form.pkgs.data.replace('\n', ' '), copr=copr, chroots=copr.chroots, repos=copr.repos, user=flask.g.user, submitted_on=int(time.time()))
        if flask.g.user.proven:
            build.memory_reqs = form.memory_reqs.data
            build.timeout = form.timeout.data
        builds_logic.BuildsLogic.new(flask.g.user, build, copr, check_authorized=False)
        db.session.commit()
        flask.flash('Build was added')
        return flask.redirect(flask.url_for('coprs_ns.copr_detail', username=username, coprname=copr.name))
    else:
        return coprs_general.copr_detail(username=username, coprname=coprname, build_form=form)

def set_tag_end_ms(tag, end_ms):
    with db_transaction():
        updated = Tag.update(lifetime_end_ms=end_ms).where(Tag.id == tag).where(Tag.lifetime_end_ms == tag.lifetime_end_ms).execute()
        if updated != 1:
            return (None, False)
        return (tag.lifetime_end_ms, True)

def _save_export_countries(self, interaction, validated_export_countries):
    existing_country_mapping = {export_country.country: export_country for export_country in interaction.export_countries.all()}
    new_country_mapping = {item['country']: item for item in validated_export_countries}
    for (new_country, export_data) in new_country_mapping.items():
        status = export_data['status']
        if new_country in existing_country_mapping:
            raise NotImplementedError()
        InteractionExportCountry.objects.create(country=new_country, interaction=interaction, status=status, created_by=interaction.created_by)
        current_date = now()
        record_date = current_date if interaction.date > current_date else interaction.date
        interaction.company.add_export_country(new_country, status, record_date, interaction.created_by)

def registeropt(self, name, valuetype, where, default):
    if any((opt[0] == name for opt in self.opts)):
        return
    self.opts.append((name, valuetype, where, default))

def announce(self, negotiated, nlris=None, mps=None):
    asn4 = negotiated.asn4
    local_as = negotiated.local_as
    peer_as = negotiated.peer_as
    msg_size = negotiated.msg_size
    attr = self.attributes.pack(asn4, local_as, peer_as)
    if nlris is None and mps is None:
        packed_nlri = []
        packed_mp = []
        for nlri in self.nlris:
            (afi, safi) = (nlri.afi, nlri.safi)
            addpath = negotiated.addpath.send(afi, safi)
            if nlri.family() in negotiated.families:
                if afi == AFI.ipv4 and safi in [SAFI.unicast, SAFI.multicast] and (nlri.nexthop == self.attributes.get(AID.NEXT_HOP, None)):
                    packed_nlri.append(nlri)
                else:
                    packed_mp.append(nlri)
        else:
            packed_nlri = nlris
            packed_mp = mps
    if not packed_nlri and (not packed_mp):
        return ''
    return self.make_message(msg_size, attr, MPRNLRI(packed_mp).pack(addpath), ''.join((nlri.pack(addpath) for nlri in packed_nlri)))

def write_port_csv(self, sta_count, ul, dl, ul_pdu, dl_pdu, atten, eid_name, port_data, latency, jitter, tput):
    row = [self.epoch_time, self.time_stamp(), sta_count, ul, ul, dl, dl, dl_pdu, dl_pdu, ul_pdu, ul_pdu, atten, eid_name]
    row = row + [port_data['bps rx'], port_data['bps tx'], port_data['rx-rate'], port_data['tx-rate'], port_data['signal'], port_data['ap'], port_data['mode'], latency, jitter, tput]
    if self.ap_read:
        if len(ap_row) == len(self.ap_stats_col_titles):
            for col in ap_row:
                row.append(col)
    writer = self.port_csv_writers[eid_name]
    writer.writerow(row)
    self.port_csv_files[eid_name].flush()

def deleteBlocks(self):
    logging.info('Checking if there are block rules to be deleted...')
    completedBlocksDict = self.getCompletedBlocks.execute(transaction=False)
    if not completedBlocksDict:
        logging.info('No candidate blocks found for rule deletion.')
        return
    logging.info('Found %d completed blocks', len(completedBlocksDict))
    logging.debug('Full completedBlocksDict: %s', pformat(completedBlocksDict))
    deletableWfsDict = set(self.getDeletableWorkflows.execute())
    if not deletableWfsDict:
        logging.info('No workflow chains (Parent + child workflows) in fully terminal state found. Skipping block level rule deletion in the current run.')
        return
    logging.info('Found %d workflows in terminal state.', len(deletableWfsDict))
    logging.debug('Full deletableWfsDict: %s', pformat(deletableWfsDict))
    now = int(time.time())
    blockDict = {}
    for block in completedBlocksDict.values():
        if block['workflowNames'].issubset(deletableWfsDict) and now - block['blockCreateTime'] > self.blockDeletionDelaySeconds:
            blockDict[block['blockName']] = block
    logging.info('Found %d final candidate blocks for rule deletion', len(blockDict))
    logging.debug('Final deletable blocks dict: %s', pformat(blockDict))
    for blocksSlice in grouper(blockDict, self.delBlockSlicesize):
        logging.info('Handling %d candidate blocks', len(blocksSlice))
        containerDict = {}
        for blockName in blocksSlice:
            container = blockDict[blockName]['dataset']

