        to_copy_to = [os.path.join(destination, i) for i in file_list]
        for (this_src, this_dst) in zip(to_copy, to_copy_to):
            splitted_list = self._os_path_split_asunder(this_dst)
            does_dir_exist = ''
            for this_dir in splitted_list[:-1]:
                does_dir_exist = os.path.join(does_dir_exist, this_dir)
                try:
                    self.mkdir(does_dir_exist)
                except OSError as e:
                    if 'File exists' in e.message:
                        pass
            if self.isdir(this_src):
                return self.copytree(this_src, this_dst, dereference)
            else:
                return self.copyfile(this_src, this_dst)
    elif self.isdir(source):
        return self.copytree(source, destination, dereference)
    else:
        return self.copyfile(source, destination)

def prepare_state(self, src_tokens: Tensor, *, prefix_tokens: Optional[Tensor]=None) -> BeamSearchState:
    (bsz, src_len) = src_tokens.size()[:2]
    beam_size = self.beam_size
    max_len = min(self.max_len, 2 * src_len + 10)
    order = torch.arange(bsz, dtype=torch.int64, device=src_tokens.device).view(-1, 1).repeat(1, beam_size).view(-1)
    scores = torch.zeros(size=(bsz * beam_size, max_len + 2), dtype=torch.float32, device=src_tokens.device)
    tokens = torch.full(size=(bsz * beam_size, max_len + 2), fill_value=self.tokenizer.PAD, dtype=torch.long, device=src_tokens.device)
    if prefix_tokens is not None:
        tokens[:, 0] = prefix_tokens.T[0].view(-1, 1).repeat(1, beam_size).view(-1)
    else:
        tokens[:, 0] = self.tokenizer.BOS
    finished_mask = torch.zeros(size=(bsz, beam_size), dtype=torch.bool, device=src_tokens.device)
    return BeamSearchState(max_len=max_len, tokens=tokens, scores=scores, finished_mask=finished_mask, order=order, step=0)

