def purestr(x, with_args=False):
    sargs = ()
    if not isinstance(x, Basic):
        rv = str(x)
    elif not x.args:
        rv = srepr(x)
    else:
        args = x.args
        sargs = tuple(map(purestr, args))
        rv = '%s(%s)' % (type(x).__name__, ', '.join(sargs))
    if with_args:
        rv = (rv, sargs)
    return rv

