def eval(cls, n, a, b, x):
    if a == b:
        if a == -S.Half:
            return RisingFactorial(S.Half, n) / factorial(n) * chebyshevt(n, x)
        elif a == S.Zero:
            return legendre(n, x)
        elif a == S.Half:
            return RisingFactorial(3 * S.Half, n) / factorial(n + 1) * chebyshevu(n, x)
        else:
            return RisingFactorial(a + 1, n) / RisingFactorial(2 * a + 1, n) * gegenbauer(n, a + S.Half, x)
    elif b == -a:
        return gamma(n + a + 1) / gamma(n + 1) * (1 + x) ** (a / 2) / (1 - x) ** (a / 2) * assoc_legendre(n, -a, x)
    elif a == -b:
        return gamma(n - b + 1) / gamma(n + 1) * (1 - x) ** (b / 2) / (1 + x) ** (b / 2) * assoc_legendre(n, b, x)
    if not n.is_Number:
        if x.could_extract_minus_sign():
            return S.NegativeOne ** n * jacobi(n, b, a, -x)
        if x == S.Zero:
            return 2 ** (-n) * gamma(a + n + 1) / (gamma(a + 1) * factorial(n)) * hyper([-b - n, -n], [a + 1], -1)
        if x == S.One:
            return RisingFactorial(a + 1, n) / factorial(n)
        elif x == S.Infinity:
            if n.is_positive:
                if (a + b + 2 * n).is_integer:
                    raise ValueError('Error. a + b + 2*n should not be an integer.')
                return RisingFactorial(a + b + n + 1, n) * S.Infinity
    else:
        return jacobi_poly(n, a, b, x)

def _print_PythonPrint(self, expr):
    self._additional_imports.add('stdio')
    end = '\n'
    sep = ' '
    code = ''
    empty_end = ValuedVariable(NativeString(), 'end', value='')
    space_end = ValuedVariable(NativeString(), 'end', value=' ')
    kwargs = [f for f in expr.expr if isinstance(f, ValuedVariable)]
    for f in kwargs:
        if isinstance(f, ValuedVariable):
            if f.name == 'sep':
                sep = str(f.value)
            elif f.name == 'end':
                end = str(f.value)
    args_format = []
    args = []
    orig_args = [f for f in expr.expr if not isinstance(f, ValuedVariable)]

    def formatted_args_to_printf(args_format, args, end):
        args_format = sep.join(args_format)
        args_format += end
        args_format = self._print(LiteralString(args_format))
        args_code = ', '.join([args_format, *args])
        return 'printf({});\n'.format(args_code)
    if len(orig_args) == 0:
        return formatted_args_to_printf(args_format, args, end)
    for (i, f) in enumerate(orig_args):
        if isinstance(f, FunctionCall) and isinstance(f.dtype, NativeTuple):
            tmp_list = self.extract_function_call_results(f)
            tmp_arg_format_list = []
            for a in tmp_list:
                (arg_format, arg) = self.get_print_format_and_arg(a)
                tmp_arg_format_list.append(arg_format)
                args.append(arg)
            args_format.append('({})'.format(', '.join(tmp_arg_format_list)))
            assign = Assign(tmp_list, f)
            self._additional_code += self._print(assign)
        elif f.rank > 0:
            if args_format:
                code += formatted_args_to_printf(args_format, args, sep)
                args_format = []
                args = []
            for_index = Variable(NativeInteger(), name=self._parser.get_new_name('i'))
            self._additional_declare.append(for_index)
            max_index = PyccelMinus(PythonLen(orig_args[i]), LiteralInteger(1), simplify=True)
            for_range = PythonRange(max_index)
            print_body = [orig_args[i][for_index]]
            if orig_args[i].rank == 1:
                print_body.append(space_end)
            for_body = [PythonPrint(print_body)]
            for_loop = For(for_index, for_range, for_body)
            for_end = ValuedVariable(NativeString(), 'end', value=']' + end if i == len(orig_args) - 1 else ']')
            body = CodeBlock([PythonPrint([LiteralString('['), empty_end]), for_loop, PythonPrint([orig_args[i][max_index], for_end])], unravelled=True)
            code += self._print(body)
        else:
            (arg_format, arg) = self.get_print_format_and_arg(f)
            args_format.append(arg_format)
            args.append(arg)
    if args_format:
        code += formatted_args_to_printf(args_format, args, end)
    return code

def _format_class_body(statements: List, context: Context) -> (List[str], int):
    formatted_lines = []
    previously_processed_line_number = context.previously_processed_line_number
    for statement in statements:
        formatted_lines += _reconstruct_blank_lines_in_range(previously_processed_line_number, statement.line, context.comments, ' ' * context.indent)
        previously_processed_line_number = statement.line
        if statement.data == 'tool_stmt':
            formatted_lines.append('{}tool'.format(' ' * context.indent))
        elif statement.data == 'class_def':
            name = statement.children[0].value
            formatted_lines.append('{}class {}:'.format(' ' * context.indent, name))
            (class_lines, last_processed_line) = _format_class_body(statement.children[1:], Context(indent=context.indent + 4, previously_processed_line_number=previously_processed_line_number, comments=context.comments))
            formatted_lines += class_lines
            previously_processed_line_number = last_processed_line
        if context.comments[statement.line] is not None:
            formatted_lines[-1] = '{}  {}'.format(formatted_lines[-1], context.comments[statement.line])
    formatted_lines += _reconstruct_blank_lines_in_range(previously_processed_line_number, len(statements), context.comments, ' ' * context.indent)
    return (formatted_lines, previously_processed_line_number)

