def regularization(self, lbd_w: float=1.0, lbd_b: float=1.0) -> tf.Tensor:
    loss = 0.0
    for l in self.ml_layer:
        loss += l.regularization(lbd_w=lbd_w, lbd_b=lbd_b)
    return loss

def frsw_allocate_udp_port(self, request):
    if request is None:
        self.send_param_error()
        return
    if not isinstance(request, dict) or 'id' not in request or 'port_id' not in request:
        self.send_param_error()
        return
    log.debug('received request {}'.format(request))
    frsw_id = request['id']
    if frsw_id not in self._frame_relay_switches:
        self.send_custom_error("Frame relay switch id {} doesn't exist".format(frsw_id))
        return
    frsw = self._frame_relay_switches[frsw_id]
    try:
        response = self.allocate_udp_port(frsw)
    except DynamipsError as e:
        self.send_custom_error(str(e))
        return
    response['port_id'] = request['port_id']
    self.send_response(response)

def condense_to_fragments(self, value, fragments=None, w_power=1):
    if fragments is None:
        fragments = [[index] for index in range(self.part.natom)]
    else:
        segments = sorted([item for frag in fragments for item in frag])
        segments = np.array(segments)
        if segments.size != self.numbers.size:
            raise ValueError('Items in Fragments should uniquely represent all atoms.')
        if not np.array_equal(segments, np.arange(self.part.natom)):
            raise ValueError('Fragments must contain all atom indices exactly once.')
    condensed = np.zeros(len(fragments))
    for (index, frag) in enumerate(fragments):
        weight = np.zeros(self.grid.points.shape[0])
        for item in frag:
            weight += self.part.cache.load('at_weights', item)
        share = self.grid.integrate(weight ** w_power, value)
        condensed[index] = share
    return condensed

def condense_to_fragments(self, property, fragments, w_power=1):
    if fragments is None:
        fragments = [[index] for index in range(self.part.natom)]
    else:
        segments = sorted([item for frag in fragments for item in frag])
        segments = np.array(segments)
        if segments.size != self.numbers.size:
            raise ValueError('Items in Fragments should uniquely represent all atoms.')
    condensed = np.zeros(len(fragments))
    for (index, frag) in enumerate(fragments):
        weight = np.zeros(self.grid.points.shape[0])
        for item in frag:
            weight += self.part.cache.load('at_weights', item)
        share = self.grid.integrate(weight ** w_power, property)
        condensed[index] = share
    return condensed

