def numpify(xs, pad=0, keys=None, dtypes=None):
    is_dict = isinstance(xs, dict)
    xs_np = {} if is_dict else [0] * len(xs)
    xs_iter = xs.items() if is_dict else enumerate(xs)
    for (i, (key, x)) in enumerate(xs_iter):
        if keys is None or key in keys:
            shape = get_list_shape(x)
            if dtypes is None:
                dtype = np.int64
            else:
                dtype = dtypes[i]
            x_np = np.full(shape, pad, dtype)
            dims = len(shape)
            if dims == 0:
                x_np = x
            elif dims == 1:
                x_np[0:shape[0]] = x
            elif dims == 2:
                for (j, y) in enumerate(x):
                    x_np[j, 0:len(y)] = [ys for ys in y]
            elif dims == 3:
                for (j, ys) in enumerate(x):
                    for (k, y) in enumerate(ys):
                        x_np[j, k, 0:len(y)] = y
            else:
                raise NotImplementedError
            xs_np[key] = x_np
        else:
            xs_np[key] = x
    return xs_np

def sync_release_files(self):
    release_files = []
    for release in self.releases.values():
        release_files.extend(release)
    downloaded_files = set()
    deferred_exception = None
    for release_file in release_files:
        try:
            downloaded_file = self.download_file(release_file['url'], release_file['digests']['sha256'])
            if downloaded_file:
                downloaded_files.add(str(downloaded_file.relative_to(self.mirror.homedir)))
        except Exception as e:
            logger.exception(f"Continuing to next file after error downloading: {release_file['url']}")
            if not deferred_exception:
                deferred_exception = e
    if deferred_exception:
        raise deferred_exception
    self.mirror.altered_packages[self.name] = downloaded_files

