def release_pgcon(self, dbname, conn, *, discard=False):
    if not conn.is_healthy_to_go_back_to_pool():
        logging.warning('Connection is unhealthy and should not be returned to the pool.')
        discard = True
    self._pg_pool.release(dbname, conn, discard=discard)

def fromfile(cls, filename):
    fheader = path.splitext(filename)[0] + '.header'
    if path.isfile(fheader) and path.isfile(filename):
        with open(fheader, 'r', encoding='utf-8', errors='replace') as fd:
            for line in fd:
                if line.startswith('ArrayDesc('):
                    (_desc, shape, dtype, _axes) = eval(line.replace('ArrayDesc', '').replace('dtype', 'np.dtype'))
                    return np.fromfile(filename, dtype).reshape(shape)
        raise NicosError('no ArrayDesc line found')
    else:
        raise NicosError('file and/or corresponding .header not found')

def translate_nd(self, source: mx.nd.NDArray, bucket_key: int) -> Tuple[np.ndarray, np.ndarray, float]:
    source_length = source.shape[1]
    max_output_length = source_length * C.TARGET_MAX_LENGTH_FACTOR
    return self._get_best_from_beam(*self._beam_search(source, bucket_key, max_output_length))

def _preprocess(self, dataset, fit=False):
    blocks_by_depth = []
    for depth in range(self._total_topo_depth):
        temp_blocks = []
        for block in self._blocks:
            if self._block_topo_depth[self._block_to_id[block]] == depth and isinstance(block, preprocessor.Preprocessor):
                temp_blocks.append(block)
        if not temp_blocks:
            break
        blocks_by_depth.append(temp_blocks)
    input_node_ids = [self._node_to_id[input_node] for input_node in self.inputs]
    for blocks in blocks_by_depth:
        if fit:
            for (x, y) in dataset:
                x = nest.flatten(x)
                node_id_to_data = {node_id: temp_x for (temp_x, node_id) in zip(x, input_node_ids)}
                for block in blocks:
                    data = [node_id_to_data[self._node_to_id[input_node]] for input_node in block.inputs]
                    block.update(data, y=y)
            for block in blocks:
                block.finalize()
                nest.flatten(block.outputs)[0].shape = block.output_shape
        dataset = dataset.map(functools.partial(self._preprocess_transform, input_node_ids=input_node_ids, blocks=blocks, fit=fit))
        input_node_ids = list(sorted([self._node_to_id[block.outputs[0]] for block in blocks]))
    return dataset

def _preprocess(self, dataset, fit=False):
    blocks_by_depth = []
    processed_blocks = set()
    while True:
        temp_blocks = []
        for block in self._blocks:
            block_id = self._block_to_id[block]
            if block_id in processed_blocks:
                continue
            if isinstance(block, preprocessor.Preprocessor):
                inputs_ready = True
                for input_node in block.inputs:
                    input_id = self._node_to_id[input_node]
                    input_block = None
                    for b in self._blocks:
                        if b.outputs and self._node_to_id[b.outputs[0]] == input_id:
                            input_block = b
                            break
                    if input_block and self._block_to_id[input_block] not in processed_blocks:
                        inputs_ready = False
                        break
                if inputs_ready:
                    temp_blocks.append(block)
        if not temp_blocks:
            break
        blocks_by_depth.append(temp_blocks)
        for block in temp_blocks:
            processed_blocks.add(self._block_to_id[block])
    input_node_ids = [self._node_to_id[input_node] for input_node in self.inputs]
    for blocks in blocks_by_depth:
        if fit:
            for (x, y) in dataset:
                x = nest.flatten(x)
                node_id_to_data = {node_id: temp_x for (temp_x, node_id) in zip(x, input_node_ids)}
                for block in blocks:
                    data = [node_id_to_data[self._node_to_id[input_node]] for input_node in block.inputs]
                    block.update(data, y=y)
            for block in blocks:
                block.finalize()
                nest.flatten(block.outputs)[0].shape = block.output_shape
        dataset = dataset.map(functools.partial(self._preprocess_transform, input_node_ids=input_node_ids, blocks=blocks, fit=fit))
        input_node_ids = list(sorted([self._node_to_id[block.outputs[0]] for block in blocks]))
    return dataset

def _compute_reservations_count(self):
    pms_reservation_obj = self.env['pms.reservation']
    for record in self:
        record.reservations_count = pms_reservation_obj.search_count([('partner_id.id', 'child_of', record.id if isinstance(record.id, int) else False)])

