def mark(testcase, security, severity):
    testcase.security_flag = security
    if security:
        if not severity:
            severity = severity_analyzer.get_security_severity(testcase.crash_type, testcase.crash_stacktrace, testcase.job_type, bool(testcase.gestures))
        testcase.security_severity = severity
        bisection.request_bisection(testcase)
    else:
        bisection.notify_bisection_invalid(testcase)
    testcase.put()
    helpers.log(f'Set security flags on testcase {testcase.key.id()} to {security}.', helpers.MODIFY_OPERATION)

def getDevice(self, dev, cls=None):
    if isinstance(dev, str):
        if dev in self.devices:
            dev = self.devices[dev]
        elif dev in self.configured_devices:
            dev = self.createDevice(dev)
        else:
            raise ConfigurationError('device %r not found in configuration' % dev)
    if not isinstance(dev, cls or Device):
        raise UsageError('dev must be an instance of %s' % (cls.__name__ if isinstance(cls, tuple) else cls.__name__))
    return dev

def execute_task(self, task_id):
    task = self.state_manager.get_task(task_id)
    if task is None:
        self.logger.error('Invalid task %s' % task_id)
        raise errors.DriverError('Invalid task %s' % task_id)
    if task.action not in self.supported_actions:
        self.logger.error("Driver %s doesn't support task action %s" % (self.driver_desc, task.action))
        raise errors.DriverError("Driver %s doesn't support task action %s" % (self.driver_desc, task.action))
    design_id = getattr(task, 'design_id', None)
    if design_id is None:
        raise errors.DriverError('No design ID specified in task %s' % task_id)
    if task.site_name is None:
        raise errors.DriverError('Not site specified for task %s.' % task_id)
    self.orchestrator.task_field_update(task.get_id(), status=hd_fields.TaskStatus.Running)
    if task.action == hd_fields.OrchestratorAction.ValidateOobServices:
        self.orchestrator.task_field_update(task.get_id(), status=hd_fields.TaskStatus.Complete, result=hd_fields.ActionResult.Success)
        return
    site_design = self.orchestrator.get_effective_site(design_id)
    target_nodes = []
    if len(task.node_list) > 0:
        target_nodes.extend([x for x in site_design.baremetal_nodes if x.get_name() in task.node_list])
    else:
        target_nodes.extend(site_design.baremetal_nodes)
    incomplete_subtasks = []
    for n in target_nodes:
        subtask = self.orchestrator.create_task(task_model.DriverTask, parent_task_id=task.get_id(), design_id=design_id, action=task.action, task_scope={'site': task.site_name, 'node_names': [n.get_name()]})
        incomplete_subtasks.append(subtask.get_id())
        runner = PyghmiTaskRunner(state_manager=self.state_manager, orchestrator=self.orchestrator, task_id=subtask.get_id(), node=n)
        runner.start()
    i = 0
    while len(incomplete_subtasks) > 0:
        for n in incomplete_subtasks:
            t = self.state_manager.get_task(n)
            if t.get_status() in [hd_fields.TaskStatus.Terminated, hd_fields.TaskStatus.Complete, hd_fields.TaskStatus.Errored]:
                incomplete_subtasks.remove(n)
        time.sleep(2)
        i = i + 1
        if i == 5:
            break
    task = self.state_manager.get_task(task.get_id())
    subtasks = map(self.state_manager.get_task, task.get_subtasks())
    success_subtasks = [x for x in subtasks if x.get_result() == hd_fields.ActionResult.Success]
    nosuccess_subtasks = [x for x in subtasks if x.get_result() in [hd_fields.ActionResult.PartialSuccess, hd_fields.ActionResult.Failure]]
    task_result = None
    if len(success_subtasks) > 0 and len(nosuccess_subtasks) > 0:
        task_result = hd_fields.ActionResult.PartialSuccess
    elif len(success_subtasks) == 0 and len(nosuccess_subtasks) > 0:
        task_result = hd_fields.ActionResult.Failure
    elif len(success_subtasks) > 0 and len(nosuccess_subtasks) == 0:
        task_result = hd_fields.ActionResult.Success
    else:
        task_result = hd_fields.ActionResult.Incomplete
    self.orchestrator.task_field_update(task.get_id(), result=task_result, status=hd_fields.TaskStatus.Complete)
    return

def get_runner(self, ast: LazyOp) -> CompiledASTRunner:
    if ast not in self.method_cache or getenv('DISABLE_METHOD_CACHE'):
        self.method_cache[ast] = self.to_program(get_optimized_linearizer(ast, self.linearizer_opts))
    return self.method_cache[ast]

def output_OU(writer, id, db_ou, stedkode, parent_stedkode, constants, url_map):
    stedkode.clear()
    stedkode.find(id)
    if stedkode.katalog_merke != 'T':
        logger.debug('Skipping ou_id == %s', id)
        return
    db_ou.clear()
    db_ou.find(id)
    ou_names = db_ou.get_names()
    ou_acronyms = db_ou.get_acronyms()
    has_any = lambda sequence, field: [x for x in sequence if x[field] is not None]
    if not has_any(ou_names, 'name') or not has_any(ou_acronyms, 'acronym'):
        logger.error('Missing name/acronym information for ou_id = %s', id)
        return
    writer.startElement('norOrgUnit')
    for (name, language) in ou_names:
        if not name:
            continue
        attributes = {}
        if language:
            attributes = {'language': language}
        output_element(writer, name, 'norOrgUnitName', attributes)
    output_element(writer, stedkode.fakultet, 'norOrgUnitFaculty')
    output_element(writer, stedkode.institutt, 'norOrgUnitDepartment')
    output_element(writer, stedkode.avdeling, 'norOrgUnitGroup')
    output_OU_parent(writer, db_ou, parent_stedkode, constants)
    for (acronym, language) in ou_acronyms:
        if not acronym:
            continue
        attributes = {}
        if language:
            attributes = {'language': language}
        output_element(writer, acronym, 'norOrgUnitAcronym', attributes)
    output_OU_address(writer, db_ou, constants)
    for row in db_ou.get_contact_info(source=constants.system_lt, type=constants.contact_phone):
        output_element(writer, row.contact_value, 'Telephone')
    for row in db_ou.get_contact_info(source=constants.system_lt, type=constants.contact_fax):
        output_element(writer, row.contact_value, 'Fax')
    key = (str(stedkode.fakultet), str(stedkode.institutt), str(stedkode.avdeling))
    for url in url_map.get(key, []):
        output_element(writer, url, 'URL')
    writer.endElement('norOrgUnit')

