def _addExtraCfg(self, cmd, devices=tuple(), use_lvmpolld=True):
    newcmd = [constants.EXT_LVM, cmd[0]]
    if devices:
        dev_filter = _buildFilter(devices)
    else:
        dev_filter = self._getCachedFilter()
    conf = _buildConfig(dev_filter=dev_filter, use_lvmpolld='1' if use_lvmpolld else '0')
    newcmd += ['--config', conf]
    if len(cmd) > 1:
        newcmd += cmd[1:]
    return newcmd

def add_flair(paragraphs: List[str], gens: Dict[str, Any]) -> List[str]:
    results = []
    flair = get_flair_gen(len(paragraphs))
    for i in range(len(paragraphs)):
        key = flair[i]
        if key == 'None':
            txt = paragraphs[i]
        elif key == 'italic':
            txt = add_md('*', paragraphs[i])
        elif key == 'bold':
            txt = add_md('**', paragraphs[i])
        elif key == 'strike-thru':
            txt = add_md('~~', paragraphs[i])
        elif key == 'quoted':
            txt = '>' + paragraphs[i]
        elif key == 'quote-block':
            txt = paragraphs[i] + '\n' + next(gens['quote-blocks'])
        elif key == 'inline-code':
            txt = paragraphs[i] + '\n' + next(gens['inline-code'])
        elif key == 'code-block':
            txt = paragraphs[i] + '\n' + next(gens['code-blocks'])
        elif key == 'math':
            txt = paragraphs[i] + '\n' + next(gens['maths'])
        elif key == 'list':
            txt = paragraphs[i] + '\n' + next(gens['lists'])
        elif key == 'emoji':
            txt = add_emoji(paragraphs[i], next(gens['emojis']))
        elif key == 'link':
            txt = add_link(paragraphs[i], next(gens['links']))
        elif key == 'picture':
            txt = paragraphs[i] + '\n' + next(gens['images'])
        results.append(txt)
    return results

@property
def states(self):
    return self._states

def add_activation_summary(x, name=None):
    ctx = get_current_tower_context()
    if ctx is not None and (not ctx.is_main_training_tower):
        return
    ndim = x.get_shape().ndims
    assert ndim >= 1, 'Summary a scalar with histogram? Maybe use scalar instead. FIXME!'
    if name is None:
        name = x.name
    with tf.name_scope('activation-summary'):
        if ndim == 1:
            tf.summary.scalar(name, x)
        else:
            tf.summary.histogram(name, x)
        tf.summary.scalar(name + '-sparsity', tf.nn.zero_fraction(x))
        tf.summary.scalar(name + '-rms', rms(x))

def _create_data_loader(self, dataset: Dataset) -> DataLoader:
    dataset_reset = returnn_dataset_wrapper.ReturnnDatasetResetMpSharedEpochCallback(dataset=dataset, epoch_mp_shared=self._epoch_mp_shared)
    wrapped_dataset = returnn_dataset_wrapper.ReturnnDatasetIterDataPipe(dataset, reset_callback=dataset_reset)
    if self._min_seq_length is not None or self._max_seq_length is not None:
        wrapped_dataset = data_pipeline.LenFilterDataPipe(wrapped_dataset, min_seq_length=self._min_seq_length, max_seq_length=self._max_seq_length)
    chunking = self.config.typed_value('chunking', None)
    min_chunk_size = self.config.typed_value('min_chunk_size', 0)
    if chunking:
        wrapped_dataset = data_pipeline.ChunkingIterDataPipe(wrapped_dataset, chunking, min_chunk_size=min_chunk_size)
    assert self.config.typed_value('batch_size') is not None, 'batch_size not defined in config'
    batch_size = self.config.typed_value('batch_size', 1)
    max_seqs = self.config.int('max_seqs', -1)
    batches_dataset = data_pipeline.BatchingIterDataPipe(wrapped_dataset, batch_size=batch_size, max_seqs=max_seqs)
    loader_opts = self.config.typed_value('torch_dataloader_opts') or {}
    assert isinstance(loader_opts, dict), f'config torch_dataloader_opts, expected dict, got {type(loader_opts)}'
    if loader_opts.get('num_workers'):
        loader_opts.setdefault('persistent_workers', True)
        loader_opts.setdefault('worker_init_fn', _data_loader_worker_init_func)
        loader_opts.setdefault('multiprocessing_context', 'spawn')
    return DataLoader(batches_dataset, collate_fn=data_pipeline.collate_batch, batch_size=None, shuffle=None, sampler=None, batch_sampler=None, **loader_opts)

def __call__(self, *args, **kwargs):
    if self.raw:
        response = self.func(request, **kwargs)
    elif self.form_param:
        content = request.forms.get(self.form_param)
        if content is None:
            raise Exception('Received a request on a webhook with a form_param defined, but that key ({}) is missing from the request.'.format(self.form_param))
        try:
            content = loads(content)
        except ValueError:
            log.debug('The form parameter is not JSON, return it as a string')
        response = self.func(content, **kwargs)
    else:
        data = try_decode_json(request)
        if not data:
            if hasattr(request, 'forms'):
                data = dict(request.forms)
            else:
                data = request.body.read().decode()
        response = self.func(data, **kwargs)
    return response if response else ''

def __call__(self, *args, **kwargs):
    name_to_find = self.func.__name__
    log.debug('All active plugin objects %s ' % get_all_active_plugin_objects())
    for obj in get_all_active_plugin_objects():
        matching_members = getmembers(obj, self.method_filter)
        log.debug('Matching members %s -> %s' % (obj, matching_members))
        if matching_members:
            (name, func) = matching_members[0]
            if self.raw:
                response = func(request, **kwargs)
            elif self.form_param:
                content = request.forms.get(self.form_param)
                if content is None:
                    raise Exception('Received a request on a webhook with a form_param defined, but that key ({}) is missing from the request.'.format(self.form_param))
                try:
                    content = loads(content)
                except ValueError:
                    log.debug('The form parameter is not JSON, return it as a string')
                response = func(content, **kwargs)
            else:
                data = try_decode_json(request)
                if not data:
                    if hasattr(request, 'forms'):
                        data = dict(request.forms)
                    else:
                        data = request.body.read().decode()
                response = func(data, **kwargs)
            return response if response else ''
    raise Exception('Problem finding back the correct Handler for func %s' % name_to_find)

def filter_tasks(self, tasks):
    try:
        if self._config.PID:
            pidlist = [int(p) for p in self._config.PID.split(',')]
            newtasks = [t for t in tasks if t.UniqueProcessId in pidlist]
            tasks = newtasks
    except (ValueError, TypeError):
        debug.warning('Caught ValueError or TypeError in filter_tasks')
        pass
    return tasks

def _cleanup_resize(self, context, instance, network_info):
    inst_base = libvirt_utils.get_instance_path(instance)
    target = inst_base + '_resize'
    attempts = 0
    while os.path.exists(target) and attempts < 5:
        shutil.rmtree(target, ignore_errors=True)
        if os.path.exists(target):
            time.sleep(random.randint(20, 200) / 100.0)
        attempts += 1
    if self.image_backend.backend(CONF.libvirt.images_type).SUPPORTS_CLONE:
        root_disk = self.image_backend.by_name(instance, 'disk')
        if root_disk.exists():
            root_disk.remove_snap(libvirt_utils.RESIZE_SNAPSHOT_NAME, ignore_errors=False)
    if instance.host != CONF.host:
        self._undefine_domain(instance)
        self.unplug_vifs(instance, network_info)
        self.unfilter_instance(instance)

def _array_indexing(array, key, key_dtype, axis):
    if issparse(array):
        if key_dtype == 'bool':
            key = np.asarray(key)
    if isinstance(key, tuple):
        key = list(key)
    return array[key] if axis == 0 else array[:, key]

def __register_login(parser):
    parser.add_argument('username', type=str, dest='username', default=getpass.getuser(), help='The username to authenticate with.')
    parser.add_argument('-d', '--deactivate', '--logout', dest='logout', action='store_true', default=argparse.SUPPRESS, help='Send a logout request to end your privileged session.')

def create_temp_user_avatar(self, user, filename, size, avatar_img, contentType=None, auto_confirm=False):
    size_from_file = os.path.getsize(filename)
    if size != size_from_file:
        size = size_from_file
    filename = os.path.split(filename)[1]
    params = {'username': user, 'filename': filename, 'size': size}
    headers = {'X-Atlassian-Token': 'no-check'}
    if contentType is not None:
        headers['content-type'] = contentType
    else:
        headers['content-type'] = self._get_mime_type(avatar_img)
    url = self._get_url('user/avatar/temporary')
    r = self._session.post(url, params=params, headers=headers, data=avatar_img)
    raise_on_error(r)
    cropping_properties = json.loads(r.text)
    if auto_confirm:
        return self.confirm_user_avatar(user, cropping_properties)
    else:
        return cropping_properties

def termdef(term):
    types = set((o.id for o in term.objects(RDF.type)))
    is_class = types & CLASS_TYPES
    is_prop = types & PROP_TYPES
    if not is_class and (not is_prop):
        return None
    if is_class:
        equiv = OWL.equivalentClass
        subof = RDFS.subClassOf
    else:
        equiv = OWL.equivalentProperty
        subof = RDFS.subPropertyOf
    predicates = [OWL.sameAs]
    if is_class:
        predicates.append(equiv)
        predicates.append(subof)
    else:
        predicates.append(equiv)
    target_term = None
    for pred in predicates:
        target_term = term.value(pred)
        if target_term:
            break
    curie = unicode((target_term or term).qname())
    if is_class:
        return curie
    range_type = term.value(RDFS.range)
    range_iri = range_type and range_type.id
    if range_iri and range_iri.startswith(XSD) or range_iri == RDFS.Literal:
        datatype = range_type.qname()
    elif OWL.DatatypeProperty in types:
        datatype = False
    else:
        datatype = None
    if types & {RDF.Property, OWL.FunctionalProperty}:
        container = None
    elif range_iri == RDF.List:
        container = '@list'
    else:
        container = None
    reverse = None if target_term else term.value(OWL.inverseOf)
    if reverse or datatype or container:
        if reverse:
            dfn = {'@reverse': unicode(reverse.qname())}
        else:
            dfn = {'@id': curie}
        if datatype:
            dfn['@type'] = datatype
        elif datatype is False:
            dfn['@language'] = None
        if container:
            dfn['@container'] = container
        return dfn
    else:
        return curie

def _setup_jobs(self, job_names, skip_missing):
    jobs = []
    for job_name in job_names:
        if job_name == 'apt-get':
            job_name = 'apt'
        selection_name = self.solv.Selection.SELECTION_NAME
        selection_provides = self.solv.Selection.SELECTION_PROVIDES
        selection = self.pool.select(job_name, selection_name | selection_provides)
        if selection.flags & self.solv.Selection.SELECTION_PROVIDES:
            log.info('--> Using capability match for {0}'.format(job_name))
        if selection.isempty():
            if skip_missing:
                log.info('--> Package {0} not found: skipped'.format(job_name))
            else:
                raise KiwiSatSolverJobError('Package {0} not found'.format(job_name))
        else:
            jobs += selection.jobs(self.solv.Job.SOLVER_INSTALL)
    return jobs

