def page_up_down_edit(self, up_down):
    current_row = self.table.selectionModel().selectedRows()[0].row()
    if up_down == self.edit_dlg.UP:
        shift = -1
    elif up_down == self.edit_dlg.DOWN:
        shift = 1
    self.table.selectRow(current_row + shift)
    _card_ids = self._card_ids_from_selection()
    card = self.database().card(_card_ids.pop(), is_id_internal=True)
    self.edit_dlg.before_apply_hook = self.unload_qt_database
    if self.edit_dlg.apply_changes():
        self.database().reload()
    self.edit_dlg.set_new_card(card)

def upload_object_via_stream(self, iterator, container, object_name, extra=None, ex_storage_class=None):
    method = 'PUT'
    params = None
    if self.supports_s3_multipart_upload:
        return self._put_object_multipart(container=container, object_name=object_name, extra=extra, stream=iterator, verify_hash=False, storage_class=ex_storage_class)
    return self._put_object(container=container, object_name=object_name, extra=extra, method=method, query_args=params, stream=iterator, verify_hash=False, storage_class=ex_storage_class)

